from math import sqrt

class Solution:

	def countDivisorsMult(self, a, n):
		prime_freq = {}
		for i in range(n):
			x = a[i]
			j = 2
			while j * j <= x:
				while x % j == 0:
					prime_freq[j] = prime_freq.get(j, 0) + 1
					x //= j
				j += 1
			if x > 1:
				prime_freq[x] = prime_freq.get(x, 0) + 1
		count = 1
		for freq in prime_freq.values():
			count *= freq + 1
		return count
